	var now_date=new Date();
	var t_year = now_date.getFullYear();
	var t_month = now_date.getMonth();
	var t_hour = now_date.getHours()
	if(t_hour < 17) {
		var t_date = now_date.getDate()+1;
		var t_day = now_date.getDay()+1;
	} else {
		var t_date = now_date.getDate()+2;
		var t_day = now_date.getDay()+2;
	}
	var t_day_str= new Array("日", "月", "火", "水", "木", "金", "土", "日", "月");
	
	//document.write(t_year+"年 "+t_month+"月 "+t_date+"日 ("+t_day_str[t_day]+")<br>");
	
	var s_date=new Date(t_year, t_month, t_date, 0, 0, 0, 0);
	var s_sec = s_date.getTime();
	
	for (var i=1 ; i<=183 ; i++) {
		var now_date=new Date(s_sec);
		var t_year = now_date.getFullYear();
		var t_month = now_date.getMonth()+1;
		if(t_month < 10) { t_month = "0"+t_month; }
		var t_hour = now_date.getHours()
		var t_date = now_date.getDate();
		if(t_date < 10) { t_date = "0"+t_date; }
		var t_day = now_date.getDay();
		var t_day_str= new Array("日", "月", "火", "水", "木", "金", "土");
		
		var date_temp = t_year+"年 "+t_month+"月 "+t_date+"日 ("+t_day_str[t_day]+")"; 
	//	document.write(date_temp+"<br>");
		if(i < 183) {
			$('#start_date').append($('<option>').html(date_temp).val(i));
		}
		if(i > 1) {
			$('#end_date').append($('<option>').html(date_temp).val(i));
		}
			s_sec = s_sec+86400000;
	}

